import java.util.Scanner;

public class Main {
    static final int MOD = 1000000007;

    static int add_mod(int a, int b) {
        a += b;
        if (a >= MOD) a -= MOD;
        return a;
    }

    static int multiply_mod(int a, int b) {
        long product = 1L * a * b;
        if (product >= MOD) product %= MOD;
        return (int) product;
    }

    static class Matrix {
        int N, M;
        int[][] data;

        public Matrix(int N, int M) {
            this.N = N;
            this.M = M;
            data = new int[N][M];
        }

        void zero() {
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < M; j++) {
                    data[i][j] = 0;
                }
            }
        }

        void identity() {
            zero();
            int limit = Math.min(N, M);
            for (int i = 0; i < limit; i++) {
                data[i][i] = 1;
            }
        }

        Matrix transpose() {
            Matrix result = new Matrix(M, N);
            result.zero();
            for (int i = 0; i < M; i++) {
                for (int j = 0; j < N; j++) {
                    result.data[i][j] = data[j][i];
                }
            }
            return result;
        }

        int[] getRow(int row) {
            return data[row];
        }

        Matrix add(Matrix other) {
            Matrix sum = new Matrix(N, M);
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < M; j++) {
                    sum.data[i][j] = add_mod(this.data[i][j], other.data[i][j]);
                }
            }
            return sum;
        }

        Matrix multiplyScalar(int scalar) {
            Matrix result = new Matrix(N, M);
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < M; j++) {
                    result.data[i][j] = multiply_mod(this.data[i][j], scalar);
                }
            }
            return result;
        }

        static Matrix multiply(Matrix a, Matrix b) {
            Matrix out = new Matrix(a.N, b.M);
            out.zero();
            for (int i = 0; i < a.N; i++) {
                for (int j = 0; j < a.M; j++) {
                    if (a.data[i][j] != 0) {
                        for (int k = 0; k < b.M; k++) {
                            if (b.data[j][k] != 0) {
                                out.data[i][k] = add_mod(out.data[i][k], multiply_mod(a.data[i][j], b.data[j][k]));
                            }
                        }
                    }
                }
            }
            return out;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        int K = sc.nextInt();

        // Initialize arrays
        int maxI = 65; // maximum number of iterations
        Matrix[][] A = new Matrix[maxI][K];
        Matrix[][] S = new Matrix[maxI][K];
        Matrix[][] P = new Matrix[maxI][K];

        for (int i = 0; i < maxI; i++) {
            for (int j = 0; j < K; j++) {
                A[i][j] = new Matrix(35, 35);
                A[i][j].zero();
            }
        }

        // Initialize A[0][i]
        for (int i = 0; i < K; i++) {
            A[0][i].identity();
            A[0][i].data[i][K - 1] = 1; // set A[0][i][i][j] = 1 for j=0..K
        }

        long length = K;
        int i = 1;
        while (length <= n) {
            // Compute S[i-1][j]
            for (int j = 0; j < K; j++) {
                S[i - 1][j] = new Matrix(35, 35);
                S[i - 1][j].zero();
            }
            S[i - 1][K - 1] = A[i - 1][K - 1];
            for (int j = K - 2; j >= 0; j--) {
                S[i - 1][j] = Matrix.multiply(A[i - 1][j], S[i - 1][j + 1]);
            }

            // Compute P[i-1][j]
            for (int j = 0; j < K; j++) {
                P[i - 1][j] = new Matrix(35, 35);
                P[i - 1][j].zero();
            }
            P[i - 1][0] = A[i - 1][0];
            for (int j = 1; j < K; j++) {
                P[i - 1][j] = Matrix.multiply(P[i - 1][j - 1], A[i - 1][j]);
            }

            // Compute A[i][j]
            for (int j = 0; j < K; j++) {
                A[i][j] = new Matrix(35, 35);
            }
            A[i][0] = S[i - 1][0];
            for (int j = 1; j < K; j++) {
                A[i][j] = Matrix.multiply(S[i - 1][j], P[i - 1][j - 1]);
            }

            length *= K;
            i++;
        }

        // Convert n to base K digits
        int[] digits = new int[65];
        int lenDigits = 0;
        long tempN = n;
        while (tempN > 0) {
            digits[lenDigits++] = (int) (tempN % K);
            tempN /= K;
        }

        // Initialize answer matrix
        Matrix answer = new Matrix(35, 35);
        answer.identity();

        int s = 0;
        for (int idx = lenDigits - 1; idx >= 0; idx--) {
            int digit = digits[idx];
            for (int j = 0; j < digit; j++) {
                answer = Matrix.multiply(answer, A[idx][(j + s) % K]);
            }
            s = (s + digit) % K;
        }

        int res = 1;
        for (int i = 0; i < K; i++) {
            res = add_mod(res, answer.data[i][K]);
        }

        System.out.println(res);
        sc.close();
    }
}

